import json

class CsvExport:
    def export(self, daten):
        return ";".join(daten)

class JsonExport:
    def export(self, daten):
        return json.dumps(daten)

EXPORTE = {"csv": CsvExport,
           "json": JsonExport}

def erzeuge_export(fmt):
    try:
        return EXPORTE[fmt]()
    except KeyError:
        raise ValueError(f"unbekannt: {fmt}")

e = erzeuge_export("csv")
print(e.export(["Ana", "Ben"]))
# Ana;Ben

class Konfig:
    _instanz = None

    def __new__(cls):
        if cls._instanz is None:
            cls._instanz = super().__new__(cls)
            cls._instanz.werte = {}
        return cls._instanz

a = Konfig()
a.werte["db"] = "schule.db"
b = Konfig()
print(a is b)         # True
print(b.werte["db"])  # schule.db

